def read_via_file(path):
    """
    Đọc VIA và loại bản ghi trùng UID.

    File có thể chứa cùng một VIA 2 lần (phần danh sách ở đầu và
    phần Data: chi tiết phía dưới). Mỗi UID chỉ được tính 1 lần.
    """
    DEFAULT_2FA = "A" * 28
    accounts = []
    seen_uids = set()

    for raw in Path(path).read_text(encoding="utf-8-sig", errors="ignore").splitlines():
        line = raw.strip()
        if not line:
            continue

        if line.lower().startswith("data:"):
            line = line.split(":", 1)[1].strip()

        if not line or "|" not in line:
            continue

        parts = [p.strip() for p in line.split("|")]
        if len(parts) < 7 or not parts[0].isdigit():
            continue

        uid = parts[0]
        if uid in seen_uids:
            continue
        seen_uids.add(uid)

        while len(parts) < 8:
            parts.append("")

        fakey = parts[2]
        compact_2fa = "".join(fakey.split())
        if not re.fullmatch(r"[A-Za-z0-9]{32}", compact_2fa):
            fakey = DEFAULT_2FA

        # QUAN TRỌNG: trong file thực tế, parts[6] có thể là một giá trị
        # khác (ví dụ chuỗi ngắn), trong khi cookie Facebook thật lại nằm
        # ngay trong toàn bộ dòng dữ liệu/remark. Vì vậy phải tìm cookie
        # trực tiếp trên nguyên dòng, không lấy cứng parts[6].
        #
        # Format cần giữ nguyên:
        # c_user=...;xs=...;fr=...;datr=...;|EAAAA...|
        cookie_match = re.search(
            r"(c_user=\d+;[^|]*\|EAAAA[^|]*\|)",
            line,
            re.IGNORECASE,
        )

        if cookie_match:
            cookie_value = cookie_match.group(1).rstrip("|")
            token_value = ""
        else:
            # Trường hợp không có phần EAAAA thì vẫn lấy toàn bộ đoạn
            # cookie bắt đầu từ c_user= cho tới dấu | kế tiếp.
            simple_cookie = re.search(r"(c_user=\d+;[^|]+)", line, re.IGNORECASE)
            if simple_cookie:
                cookie_value = simple_cookie.group(1).rstrip("|")
                token_value = ""
            else:
                cookie_value = parts[6].strip()
                token_value = parts[7].strip()

                if token_value.startswith("EAAAA"):
                    cookie_value = (
                        cookie_value.rstrip("|")
                        + "|"
                        + token_value.strip("|")
                    )
                    token_value = ""
                elif cookie_value.isdigit():
                    cookie_value = f"c_user={cookie_value}"

        accounts.append({
            "uid": uid,
            "password": parts[1],
            "fakey": fakey,
            "email": parts[3],
            "pass2": parts[4],
            "recovery_email": parts[5],
            "cookie": cookie_value or f"c_user={uid}",
            "token": token_value,
            "remark": "|".join(parts[8:]) if len(parts) > 8 else "",
            "raw": line,
        })

    return accounts


def read_proxy_file(path):
    proxies = []

    for raw in Path(path).read_text(encoding="utf-8-sig").splitlines():
        line = raw.strip()

        if not line:
            continue

        if "|" in line:
            line = line.strip("|").strip()

        if line.replace("-", "").replace(" ", "") == "":
            continue

        if "|" in line:
            continue

        line = line.replace("\\:", ":")
        pieces = line.split(":")

        if len(pieces) >= 2 and any(ch.isdigit() for ch in pieces[0]):
            proxies.append(line)

    return proxies


def create_output(accounts, proxies, output_path, proxy_type="Socks5"):
    if not accounts:
        raise ValueError("Không tìm thấy dữ liệu Via.")

    if not proxies:
        raise ValueError("Không tìm thấy Proxy.")

    if len(accounts) != len(proxies):
        raise ValueError(
            f"Số lượng không khớp:\n\nVia: {len(accounts)}\nProxy: {len(proxies)}"
        )

    blocks = []

    for account, proxy in zip(accounts, proxies):
        # Giữ nguyên toàn bộ dòng dữ liệu gốc trong Remark.
        source_remark = account.get("raw", "")
        if not source_remark:
            source_remark = "|".join([
                account.get("uid", ""),
                account.get("password", ""),
                account.get("fakey", "") or ("A" * 28),
                account.get("email", ""),
                account.get("pass2", ""),
                account.get("recovery_email", ""),
                account.get("cookie", ""),
                account.get("token", ""),
            ])

        # Chuẩn định dạng: mọi dòng dữ liệu VIA phải kết thúc bằng "|".
        source_remark = source_remark.rstrip()
        if not source_remark.endswith("|"):
            source_remark += "|"

        blocks.append(
            f"name={account['uid']}\n"
            f"remark={source_remark}\n"
            f"platform=facebook.com\n"
            f"username={account['uid']}\n"
            f"password={account['password']}\n"
            f"fakey={account['fakey']}\n"
            f"cookie={account['cookie'].rstrip(chr(124))}\n"
            f"proxytype={proxy_type}\n"
            f"proxy={proxy}\n"
            f"****************************************************"
        )

    Path(output_path).write_text(
        "\n".join(blocks) + "\n",
        encoding="utf-8"
    )


