class App:
    W = 1050
    H = 700
    BG = "#080b14"
    WHITE = "#f5f7fb"
    MUTED = "#91a0b5"
    CYAN = "#24d6ff"
    PINK = "#ff4fa8"
    GREEN = "#36e7a0"
    LINE = "#26384f"

    def __init__(self, root):
        self.root = root
        self.via_file = None
        self.proxy_file = None
        self.output_dir = None
        self.proxy_type = tk.StringVar(value="Socks5")
        self.drag_start_x = self.drag_start_y = 0
        self.root.overrideredirect(True)
        self.root.geometry(f"{self.W}x{self.H}")
        self.root.resizable(False, False)
        self.root.configure(bg=self.BG)
        self.canvas = tk.Canvas(self.root, width=self.W, height=self.H, bg=self.BG, highlightthickness=0, bd=0)
        self.canvas.pack(fill="both", expand=True)
        self._load_background()
        self._setup_eye_animation()
        self._build_style()
        self._draw_ui()
        self._install_drag_drop()
        self.root.after(100, self.update_clock)

    def _load_background(self):
        data = base64.b64decode(BG_DATA)
        self._bg_raw = data
        if Image is not None:
            image = Image.open(io.BytesIO(data)).convert("RGBA")
            if image.size != (self.W, self.H):
                image = image.resize((self.W, self.H), Image.Resampling.LANCZOS)
            overlay = Image.new("RGBA", (self.W, self.H), (3, 6, 14, 30))
            self._bg_base = Image.alpha_composite(image, overlay)
            self.bg_photo = ImageTk.PhotoImage(self._bg_base)
        else:
            self._bg_base = None
            self.bg_photo = tk.PhotoImage(data=base64.b64encode(data))
        self.bg_id = self.canvas.create_image(0, 0, image=self.bg_photo, anchor="nw")

    def _setup_eye_animation(self):
        """Hiệu ứng mắt: chớp tự nhiên + ánh đỏ nhấp nháy nhẹ."""
        self._eye_enabled = Image is not None and self._bg_base is not None
        if not self._eye_enabled:
            return

        # Tọa độ đã căn theo đúng background 1050x700 hiện tại.
        self._eye_boxes = (
            (235, 225, 515, 475),   # mắt trái
            (755, 120, 940, 315),   # mắt phải
        )

        self._eye_phase = 0.0
        self._blink_left = 0.0
        self._blink_right = 0.0
        self._blink_started = False

        # Chớp lần đầu sớm để người dùng thấy ngay hiệu ứng.
        self.root.after(1800, self._start_eye_blink)
        self.root.after(70, self._animate_eyes)

    def _start_eye_blink(self):
        if not getattr(self, "_eye_enabled", False):
            return

        # Hai mắt chớp gần nhau nhưng lệch nhẹ, tự nhiên hơn.
        self._blink_left = 1.0
        self.root.after(45, lambda: setattr(self, "_blink_right", 1.0))
        self.root.after(155, self._end_left_blink)
        self.root.after(195, self._end_right_blink)

    def _end_left_blink(self):
        self._blink_left = 0.0

    def _end_right_blink(self):
        self._blink_right = 0.0
        # Khoảng nghỉ ngẫu nhiên giữa các lần chớp.
        self.root.after(random.randint(2800, 5200), self._start_eye_blink)

    def _animate_eyes(self):
        if not getattr(self, "_eye_enabled", False):
            return

        self._eye_phase += 0.13
        pulse = (1.0 + __import__('math').sin(self._eye_phase)) * 0.5

        frame = self._bg_base.copy()
        overlay = Image.new("RGBA", (self.W, self.H), (0, 0, 0, 0))
        draw = __import__('PIL.ImageDraw', fromlist=['ImageDraw']).ImageDraw.Draw(overlay)

        for idx, (x1, y1, x2, y2) in enumerate(self._eye_boxes):
            blink = self._blink_left if idx == 0 else self._blink_right

            cx = (x1 + x2) // 2
            cy = (y1 + y2) // 2

            # Ánh đỏ thở nhẹ liên tục; khi chớp sẽ sáng mạnh hơn.
            glow_r = 48 + int(10 * pulse) + int(18 * blink)
            glow_a = 18 + int(16 * pulse) + int(48 * blink)
            draw.ellipse(
                (cx - glow_r, cy - glow_r, cx + glow_r, cy + glow_r),
                fill=(255, 25, 95, min(100, glow_a))
            )

            if blink > 0:
                # Hai mí khép dần từ trên xuống và dưới lên.
                mid = (y1 + y2) // 2
                close = int((y2 - y1) * 0.46 * blink)

                top_end = min(mid - 3, y1 + close)
                bottom_start = max(mid + 3, y2 - close)

                draw.polygon(
                    [(x1, y1), (x2, y1), (x2, top_end), (x1, top_end)],
                    fill=(4, 5, 10, 235)
                )
                draw.polygon(
                    [(x1, bottom_start), (x2, bottom_start), (x2, y2), (x1, y2)],
                    fill=(4, 5, 10, 235)
                )

                # Vệt mí đỏ mảnh khi mắt gần đóng.
                draw.line(
                    (x1 + 28, mid, x2 - 28, mid),
                    fill=(255, 55, 115, 190),
                    width=2
                )

        frame = Image.alpha_composite(frame, overlay)
        self.bg_photo = ImageTk.PhotoImage(frame)
        self.canvas.itemconfigure(self.bg_id, image=self.bg_photo)
        self.root.after(70, self._animate_eyes)

    def _build_style(self):
        style = ttk.Style(self.root)
        try: style.theme_use("clam")
        except tk.TclError: pass
        style.configure("Glass.TCombobox", fieldbackground="#0c1421", background="#0c1421", foreground=self.WHITE,
                        bordercolor=self.PINK, lightcolor=self.PINK, darkcolor=self.PINK, arrowcolor=self.PINK,
                        padding=(10, 6), font=("Segoe UI", 10))
        style.map("Glass.TCombobox", fieldbackground=[("readonly", "#0c1421")], foreground=[("readonly", self.WHITE)])

    def round_rect(self, x1, y1, x2, y2, radius, fill="", outline="", width=1, tags=None):
        r=max(0,min(int(radius),int((x2-x1)/2),int((y2-y1)/2)))
        c=self.canvas
        c.create_rectangle(x1+r,y1,x2-r,y2,fill=fill,outline="",tags=tags)
        c.create_rectangle(x1,y1+r,x2,y2-r,fill=fill,outline="",tags=tags)
        corners=[((x1,y1,x1+2*r,y1+2*r),90),((x2-2*r,y1,x2,y1+2*r),0),((x1,y2-2*r,x1+2*r,y2),180),((x2-2*r,y2-2*r,x2,y2),270)]
        for box,start in corners: c.create_arc(*box,start=start,extent=90,fill=fill,outline="",tags=tags)
        if outline:
            c.create_line(x1+r,y1,x2-r,y1,fill=outline,width=width,tags=tags)
            c.create_line(x1+r,y2,x2-r,y2,fill=outline,width=width,tags=tags)
            c.create_line(x1,y1+r,x1,y2-r,fill=outline,width=width,tags=tags)
            c.create_line(x2,y1+r,x2,y2-r,fill=outline,width=width,tags=tags)
            for box,start in corners: c.create_arc(*box,start=start,extent=90,style="arc",outline=outline,width=width,tags=tags)

    def glow_round_rect(self,*args,**kwargs):
        return self.round_rect(*args,**kwargs)

    def text(self,x,y,value,fill=None,font=("Segoe UI",10),anchor="nw",**kwargs):
        return self.canvas.create_text(x,y,text=value,fill=fill or self.WHITE,font=font,anchor=anchor,**kwargs)

