    def _fit_canvas_text(self, text, font_spec, max_width):
        """Rút gọn text bằng dấu … để không tràn khỏi vùng giao diện."""
        value = str(text or "")
        try:
            f = tkfont.Font(font=font_spec)
            if f.measure(value) <= max_width:
                return value
            ellipsis = "…"
            if f.measure(ellipsis) > max_width:
                return ""
            lo, hi = 0, len(value)
            while lo < hi:
                mid = (lo + hi + 1) // 2
                candidate = value[:mid] + ellipsis
                if f.measure(candidate) <= max_width:
                    lo = mid
                else:
                    hi = mid - 1
            return value[:lo] + ellipsis
        except Exception:
            # Fallback khi font Tk không đo được trong môi trường đặc biệt.
            limit = max(8, int(max_width / 8))
            return value if len(value) <= limit else value[:limit - 1] + "…"

    def draw_panel(self, x1, y1, x2, y2, title, subtitle, accent):
        # Giữ nguyên bố cục cũ, nhưng đưa bộ đếm lên góc phải cạnh tiêu đề.
        self.round_rect(x1, y1, x2, y2, 15, "#090c15", accent, 1)
        self.text(x1 + 15, y1 + 13, title, fill=accent, font=("Segoe UI", 14, "bold"))

        # Bộ đếm dạng badge nhỏ: nổi bật nhưng không chiếm diện tích nội dung.
        count_tag = f"count_{title.lower()}"
        self.round_rect(x2 - 62, y1 + 9, x2 - 12, y1 + 34, 10, "#0d1019", accent, 1, tags=(count_tag,))
        count_id = self.text(
            x2 - 37, y1 + 21, "0", fill=accent,
            font=("Segoe UI", 11, "bold"), anchor="center", tags=(count_tag,)
        )

        tag = f"drop_{title.lower()}"
        self.round_rect(x1 + 13, y1 + 43, x2 - 13, y2 - 10, 9, "#0d1019", accent, 1, tags=(tag,))
        self.text(x1 + 30, y1 + 62, "▱", fill=accent, font=("Segoe UI", 16, "bold"), anchor="center", tags=(tag,))
        self.text(x1 + 48, y1 + 56, "Chọn file TXT", fill="#eee2e7",
                  font=("Segoe UI", 10, "bold"), tags=(tag,))
        self.text(x1 + 48, y1 + 76, "Hoặc kéo thả file vào đây", fill="#a78e99",
                  font=("Segoe UI", 8), tags=(tag,))

        cmd = self.choose_via if title == "VIA" else self.choose_proxy
        self.canvas.tag_bind(tag, "<Button-1>", lambda e, cmd=cmd: cmd())
        self.canvas.tag_bind(tag, "<Enter>", lambda e: self.canvas.configure(cursor="hand2"))
        self.canvas.tag_bind(tag, "<Leave>", lambda e: self.canvas.configure(cursor=""))

        # Tên file nằm gọn ở đáy; số lượng dùng badge phía trên.
        name_id = self.text(
            x1 + 15, y2 - 25, "", fill="#d8c5ce",
            font=("Segoe UI", 8)
        )
        bullet_id = self.text(
            x1 + 15, y2 - 2, "", fill=self.MUTED,
            font=("Segoe UI", 1)
        )

        if title == "VIA":
            self.via_name_id = name_id
            self.via_count_id = count_id
            self.via_bullet_id = bullet_id
            self.via_stat_id = count_id
        else:
            self.proxy_name_id = name_id
            self.proxy_count_id = count_id
            self.proxy_bullet_id = bullet_id
            self.proxy_stat_id = count_id

    def update_clock(self):
        now=datetime.datetime.now(); weekdays=["Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm","Thứ Sáu","Thứ Bảy","Chủ Nhật"]
        self.canvas.itemconfigure(self.date_id,text=f"{weekdays[now.weekday()]}  •  {now:%d/%m/%Y}")
        self.canvas.itemconfigure(self.clock_id,text=now.strftime("%H:%M:%S"))
        self.root.after(250,self.update_clock)

    def update_panels(self):
        via_count = 0
        proxy_count = 0

        if self.via_file:
            try:
                via_count = len(read_via_file(self.via_file))
            except Exception:
                via_count = 0

            self.canvas.itemconfigure(
                self.via_name_id,
                text=Path(self.via_file).name,
            )
            self.canvas.itemconfigure(
                self.via_count_id,
                text=f"{via_count:,} dòng hợp lệ",
            )
            self.canvas.itemconfigure(
                self.via_bullet_id,
                text="• ĐÃ ĐỌC DỮ LIỆU",
                fill=self.GREEN,
            )
            self.canvas.itemconfigure(
                self.via_stat_id,
                text=f"{via_count:,}",
            )
        else:
            self.canvas.itemconfigure(
                self.via_name_id,
                text="Chưa chọn file",
            )
            self.canvas.itemconfigure(
                self.via_count_id,
                text="0 dòng hợp lệ",
            )
            self.canvas.itemconfigure(
                self.via_bullet_id,
                text="• CHƯA CÓ DỮ LIỆU",
                fill=self.MUTED,
            )
            self.canvas.itemconfigure(
                self.via_stat_id,
                text="0",
            )

        if self.proxy_file:
            try:
                proxy_count = len(read_proxy_file(self.proxy_file))
            except Exception:
                proxy_count = 0

            self.canvas.itemconfigure(
                self.proxy_name_id,
                text=Path(self.proxy_file).name,
            )
            self.canvas.itemconfigure(
                self.proxy_count_id,
                text=f"{proxy_count:,} dòng hợp lệ",
            )
            self.canvas.itemconfigure(
                self.proxy_bullet_id,
                text="• ĐÃ ĐỌC DỮ LIỆU",
                fill=self.GREEN,
            )
            self.canvas.itemconfigure(
                self.proxy_stat_id,
                text=f"{proxy_count:,}",
            )
        else:
            self.canvas.itemconfigure(
                self.proxy_name_id,
                text="Chưa chọn file",
            )
            self.canvas.itemconfigure(
                self.proxy_count_id,
                text="0 dòng hợp lệ",
            )
            self.canvas.itemconfigure(
                self.proxy_bullet_id,
                text="• CHƯA CÓ DỮ LIỆU",
                fill=self.MUTED,
            )
            self.canvas.itemconfigure(
                self.proxy_stat_id,
                text="0",
            )

        if via_count and proxy_count:
            if via_count == proxy_count:
                title = "SẴN SÀNG"
                detail = (
                    f"{via_count:,} Via  •  "
                    f"{proxy_count:,} Proxy"
                )
                color = self.GREEN
                icon = "✓"
            else:
                title = "LỆCH SỐ LƯỢNG"
                detail = (
                    f"Via: {via_count:,}  •  "
                    f"Proxy: {proxy_count:,}"
                )
                color = self.PINK
                icon = "!"

        elif self.via_file or self.proxy_file:
            title = "ĐANG CHỜ"
            detail = "Hãy chọn đủ Via và Proxy"
            color = "#ffd45a"
            icon = "•"

        else:
            title = "SẴN SÀNG"
            detail = "Chọn Via và Proxy"
            color = self.GREEN
            icon = "✓"

        self.canvas.itemconfigure(
            self.status_icon_id,
            text=icon,
            fill=color,
        )
        self.canvas.itemconfigure(
            self.status_title_id,
            text=title,
            fill=color,
        )
        self.canvas.itemconfigure(
            self.status_detail_id,
            text=detail,
        )

        if self.output_dir:
            output_path = str(Path(self.output_dir) / "Output_Theo_Mau.txt")
            output_font = ("Segoe UI", 8, "bold")
            output_display = self._fit_canvas_text(output_path, output_font, 150)
            self.canvas.itemconfigure(
                self.output_path_id,
                text=output_display,
            )
        else:
            self.canvas.itemconfigure(
                self.output_path_id,
                text=self._fit_canvas_text("Chưa chọn thư mục • mặc định hỏi nơi lưu khi tạo", ("Segoe UI", 8, "bold"), 150),
            )

    def choose_via(self):
        path = filedialog.askopenfilename(
            title="Chọn File Via",
            filetypes=[
                ("TXT files", "*.txt"),
                ("All files", "*.*"),
            ],
        )

        if path:
            self.set_via(path)

    def choose_proxy(self):
        path = filedialog.askopenfilename(
            title="Chọn File Proxy",
            filetypes=[
                ("TXT files", "*.txt"),
                ("All files", "*.*"),
            ],
        )

        if path:
            self.set_proxy(path)

    def set_via(self, path):
        try:
            count = len(read_via_file(path))
            if count <= 0:
                raise ValueError("File Via không có dòng hợp lệ.")
            self.via_file = path
            self.update_panels()
        except Exception as e:
            messagebox.showerror("File Via", str(e))

    def set_proxy(self, path):
        try:
            count = len(read_proxy_file(path))
            if count <= 0:
                raise ValueError("File Proxy không có dòng hợp lệ.")
            self.proxy_file = path
            self.update_panels()
        except Exception as e:
            messagebox.showerror("File Proxy", str(e))

    # -------------------------
    # Output
    # -------------------------

    def choose_output_dir(self):
        path = filedialog.askdirectory(
            title="Chọn thư mục lưu"
        )

        if path:
            self.output_dir = path
            self.update_panels()

    def create(self):
        try:
            if not self.via_file or not self.proxy_file:
                raise ValueError(
                    "Hãy chọn đủ File Via và File Proxy."
                )

            accounts = read_via_file(self.via_file)
            proxies = read_proxy_file(self.proxy_file)

            if len(accounts) != len(proxies):
                raise ValueError(
                    f"Số lượng không khớp:\n\n"
                    f"Via: {len(accounts):,}\n"
                    f"Proxy: {len(proxies):,}"
                )

            if self.output_dir:
                output = str(
                    Path(self.output_dir) /
                    "Output_Theo_Mau.txt"
                )
            else:
                output = filedialog.asksaveasfilename(
                    title="Lưu file kết quả",
                    defaultextension=".txt",
                    initialfile="Output_Theo_Mau.txt",
                    filetypes=[
                        ("TXT files", "*.txt")
                    ],
                )

            if not output:
                return

            create_output(
                accounts,
                proxies,
                output,
                self.proxy_type.get(),
            )

            messagebox.showinfo(
                "Hoàn tất",
                f"Đã tạo file thành công:\n\n{output}\n\n"
                f"Via: {len(accounts):,}\n"
                f"Proxy: {len(proxies):,}",
            )

        except Exception as e:
            messagebox.showerror(
                "Lỗi",
                str(e),
            )

    # -------------------------
    # Reset
    # -------------------------

    def reset(self):
        self.via_file = None
        self.proxy_file = None
        self.output_dir = None
        self.proxy_type.set("Socks5")
        self.update_panels()

    # -------------------------
    # Drag & Drop
    # -------------------------

    def handle_drop(self, files):
        """Nhận danh sách file TXT được kéo/thả vào cửa sổ."""
        for path in files:
            path = str(path).strip().strip('"')
            if not path or not path.lower().endswith(".txt"):
                continue

            try:
                via_count = len(read_via_file(path))
                proxy_count = len(read_proxy_file(path))

                if via_count > 0:
                    self.set_via(path)
                elif proxy_count > 0:
                    self.set_proxy(path)
                else:
                    messagebox.showwarning(
                        "File TXT",
                        f"Không nhận diện được file:\n\n{Path(path).name}\n\n"
                        "File phải là Via hoặc Proxy hợp lệ."
                    )
            except Exception as e:
                messagebox.showerror(
                    "Kéo thả TXT",
                    f"Không đọc được file:\n\n{Path(path).name}\n\n{e}"
                )

    def _install_drag_drop(self):
        """
        Cài kéo-thả bằng tkinterdnd2.
        Quan trọng: root phải là TkinterDnD.Tk() ngay từ đầu.
        """
        self._drop_enabled = False

        if TkinterDnD is None or DND_FILES is None:
            print("Kéo-thả: CHƯA CÀI tkinterdnd2")
            return

        try:
            self.root.drop_target_register(DND_FILES)
            self.root.dnd_bind("<<Drop>>", self._on_drop)

            self.canvas.drop_target_register(DND_FILES)
            self.canvas.dnd_bind("<<Drop>>", self._on_drop)

            self._drop_enabled = True
            print("Kéo-thả TXT: ĐÃ BẬT")
        except Exception as e:
            print("Không thể bật kéo thả:", repr(e))

    def _on_drop(self, event):
        """Đọc danh sách file Windows gửi qua TkDnD."""
        try:
            raw = str(getattr(event, "data", "") or "")
            if not raw:
                return

            try:
                paths = list(self.root.tk.splitlist(raw))
            except tk.TclError:
                paths = [raw]

            cleaned = []
            for item in paths:
                item = str(item).strip()

                # Xử lý đường dẫn dạng {C:/folder/file name.txt}
                if len(item) >= 2 and item.startswith("{") and item.endswith("}"):
                    item = item[1:-1]

                item = item.strip('"').strip()
                if item:
                    cleaned.append(item)

            txt_files = [
                p for p in cleaned
                if p.lower().endswith(".txt")
            ]

            if txt_files:
                self.handle_drop(txt_files)
            else:
                messagebox.showwarning(
                    "Kéo thả TXT",
                    "Vui lòng kéo file .txt vào cửa sổ chương trình."
                )

        except Exception as e:
            messagebox.showerror(
                "Kéo thả TXT",
                f"Không đọc được file kéo vào.\n\n{e}"
            )

    def close_app(self):
        """Close normally; TkDnD has no native ctypes callback to restore."""
        try:
            self.root.destroy()
        except Exception:
            pass

    def start_move(self, event):
        self.drag_start_x = event.x_root
        self.drag_start_y = event.y_root

    def do_move(self, event):
        dx = event.x_root - self.drag_start_x
        dy = event.y_root - self.drag_start_y

        current_x = self.root.winfo_x()
        current_y = self.root.winfo_y()

        self.root.geometry(
            f"+{current_x + dx}+{current_y + dy}"
        )

        self.drag_start_x = event.x_root
        self.drag_start_y = event.y_root


